const steps = $json.intermediateSteps || [];
const allowed = new Set();
function canonical(v) {
  const s = String(v).replace(/[\s\u00a0\u202f]/g,'').replace(',','.');
  const p = s.split('.');
  return p[0].replace(/^\+/,'') + '.' + (p[1] || '').padEnd(2,'0');
}
function collect(v) {
  if ((typeof v === 'string' || typeof v === 'number') && /^-?\d+(\.\d+)?$/.test(String(v))) {
    const s = String(v);
    allowed.add(canonical(s)); allowed.add(canonical(s.replace(/^-/,'')));
  } else if (Array.isArray(v)) v.forEach(collect);
  else if (v && typeof v === 'object') Object.values(v).forEach(collect);
}
let evidence = steps.length > 0;
for (const step of steps) {
  try {
    const result = JSON.parse(step.observation);
    if (!Array.isArray(result) || !result.every(r => r.result && typeof r.result === 'object')) evidence = false;
    collect(result);
  } catch { evidence = false; }
}
function supported(sentence) {
  const text = sentence.replace(/\*\*/g,'');
  for (const m of text.matchAll(/(-?\d[\d \u00a0\u202f]*(?:[.,]\d{1,2})?)\s*(?:Kč|CZK|EUR|USD|GBP|PLN|CHF|%)/g)) {
    if (!allowed.has(canonical(m[1]))) return false;
  }
  const withoutDates = text.replace(/\b\d{4}-\d{2}-\d{2}\b|\b\d{1,2}\.\d{1,2}\.\d{4}\b/g,'');
  for (const m of withoutDates.matchAll(/-?\d(?:[\d \u00a0\u202f]*\d)?(?:[.,]\d{1,2})?/g)) {
    const s = m[0].replace(/[\s\u00a0\u202f]/g,'');
    if (!/[.,]/.test(s) && (+s <= 31 || (+s >= 1900 && +s <= 2100))) continue;
    if (!allowed.has(canonical(s))) return false;
  }
  return true;
}
const list = $json.transactionList;
if (list?.required) {
  const verified = evidence && list.ready === true && steps.some(s => s.action?.tool === 'search_transactions');
  return [{json:{output:verified ? $json.output+'\n\nVýsledky vycházejí pouze z importovaných dat; úplnost výpisů není zaručena.' : 'Pro výpis chybí ověřené řádky z databáze. Upřesněte prosím období nebo filtr.',
    needsRetry:!verified && $runIndex<2,verification:{verified,filteredSentences:0,tools:steps.map(s=>s.action.tool),responseKind:'transactions',renderedRows:verified?list.rows:0,matchCount:verified?list.total:null,truncated:verified?list.truncated:false},intermediateSteps:steps}}];
}
const sentences = String($json.output || '').split(/(?<=[.!?])\s+(?=[A-ZÁČĎÉĚÍŇÓŘŠŤÚŮÝŽ*(])/);
const kept = sentences.filter(supported);
const verified = evidence && kept.length > 0;
const output = verified
  ? kept.join(' ') + '\n\nVýsledky vycházejí pouze z importovaných dat; úplnost výpisů není zaručena.'
  : 'Pro tento dotaz nemám ověřenou odpověď z databáze. Zkuste prosím dotaz upřesnit včetně období.';
return [{json:{output,needsRetry:!verified && $runIndex < 2,verification:{verified,filteredSentences:sentences.length-kept.length,tools:steps.map(s=>s.action.tool)},intermediateSteps:steps}}];

const original = $('Finance Chat').first().json;
const hint = $json.verification?.responseKind === 'transactions'
  ? 'Verification requires a fresh search_transactions call with reply_format="transactions". Preserve the original task, dates, and filters from the conversation.'
  : 'The previous draft failed database verification. Call the appropriate database tool again and answer only from its result. Preserve the original user request.';
return [{json:{...original,retryHint:hint}}];

// Render exact database rows without asking the language model to copy money.
const steps = $json.intermediateSteps || [];
const question = String($('Finance Chat').first().json.chatInput || '').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const requested = /\b(vypis|vypsat|vysat|seznam|zobraz|ukaz)\b/.test(question) && /transakc|platb/.test(question);
let result;
for (const step of steps) {
  if (step.action?.tool !== 'search_transactions') continue;
  try {
    const rows = JSON.parse(step.observation);
    for (const row of rows) if (row.result && Array.isArray(row.result.transactions)) result = row.result;
  } catch {}
}
const required = requested || result?.reply_format === 'transactions';
if (!required) return [{json:{...$json,transactionList:{required:false,ready:false}}}];
const valid = result && Number.isSafeInteger(result.match_count) && result.match_count >= result.transactions.length &&
  typeof result.truncated === 'boolean' && result.transactions.length <= 50 &&
  result.transactions.every(r => /^-?\d+\.\d{2}$/.test(r.amount) && /^\d{4}-\d{2}-\d{2}$/.test(r.transaction_date) && /^[A-Z]{3}$/.test(r.currency));
if (!valid) return [{json:{...$json,transactionList:{required:true,ready:false}}}];
const cell = value => String(value ?? '—').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')
  .replace(/[|\[\]*_`\\]/g,c=>'&#'+c.charCodeAt(0)+';').replace(/[\r\n]+/g,' ');
const money = value => {
  const [whole, fraction] = value.split('.');
  return whole.replace(/\B(?=(\d{3})+(?!\d))/g,' ') + ',' + fraction;
};
const categories = {Housing:'Bydlení',Groceries:'Potraviny',Restaurants:'Restaurace',Transport:'Doprava',Shopping:'Nákupy',Healthcare:'Zdraví',Subscriptions:'Předplatné',Entertainment:'Zábava',Income:'Příjmy',Transfers:'Převody',Other:'Ostatní'};
const types = {income:'Příjem',expense:'Výdaj',refund:'Vratka',transfer:'Vlastní převod'};
const lines = result.transactions.map(r => '| ' + [r.transaction_date,r.description,r.merchant,money(r.amount),r.currency,categories[r.category] || r.category,types[r.transaction_type] || r.transaction_type].map(cell).join(' | ') + ' |');
const count = result.transactions.length;
const period = result.start_date && result.end_date_exclusive ? 'Období: od ' + cell(result.start_date) + ' do ' + cell(result.end_date_exclusive) + ' (konec nezahrnut). ' : '';
const partial = result.truncated || count < result.match_count;
const heading = period + 'Zobrazeno ' + count + ' z ' + result.match_count + ' odpovídajících transakcí (' + cell(result.currency) + ').';
const table = count ? '\n\n| Datum | Popis | Obchodník | Částka | Měna | Kategorie | Typ |\n| --- | --- | --- | ---: | --- | --- | --- |\n' + lines.join('\n') : '\n\nPro zadané filtry nejsou žádné transakce.';
const note = partial ? '\n\nVýpis je omezen na 50 řádků, seřazených od nejvyšší absolutní částky. Pro další řádky zúžte období nebo filtr.' : '';
return [{json:{...$json,output:heading+table+note,transactionList:{required:true,ready:true,rows:count,total:result.match_count,truncated:partial}}}];
